export default {"id":"sounddesign-level-15","number":15,"title":"Bonus Tracks","skillBand":"Textbook","duration":"From the course textbook","summary":"- Master Surge XT's Formula Modulator engine: evaluating real-time mathematical equations at audio and control rates. - Write custom mathematical expressions using variables (x, y, t), trigonometric functions (, ,), and logic conditionals.","modules":[{"id":"sounddesign-m-1-1","code":"1","title":"Bonus Section B1 — Advanced Math & Formula Modulators","blurb":"- Master Surge XT's Formula Modulator engine: evaluating real-time mathematical equations at audio and control rates. - Write custom mathematical expressions using variables (x, y, t), trigonometric functions (, ,), and logic conditionals.","outcomes":[],"sources":[],"practiceFocus":[],"checkpoints":[],"lessons":[{"id":"sounddesign-l-o-63","title":"Section overview","blocks":[{"type":"step","title":"Learning Objectives","blocks":[{"type":"list","items":["Master Surge XT's <strong>Formula Modulator</strong> engine: evaluating real-time mathematical equations at audio and control rates.","Write custom mathematical expressions using variables (x, y, t), trigonometric functions (, ,), and logic conditionals.","Construct chaotic mathematical attractors (Lorenz, Chua) and algorithmic sample-and-hold generators.","Apply mathematical formulas to generate unpredictable generative filter sweeps and rhythmic modulations."],"ordered":false}]}],"minutes":8},{"id":"sounddesign-l-b","title":"B1.1 — The Surge XT Formula Modulator Engine","blocks":[{"type":"step","title":"B1.1 — The Surge XT Formula Modulator Engine","blocks":[{"type":"prose","html":"In Surge XT, setting any LFO block to <strong><code>Formula</code></strong> replaces traditional geometric wave generators with a mathematical code evaluator:"},{"type":"prose","html":"<pre style=\"white-space:pre-wrap;font-family:ui-monospace,monospace\">[ FORMULA EVALUATOR ] ===(Calculates y(t) every sample)===&gt; [ MODULATION VALUE (-1.0 to +1.0) ]</pre>"},{"type":"prose","html":"<pre style=\"white-space:pre-wrap;font-family:ui-monospace,monospace\">+------------------+--------------------------------------------------------------------+\n| Formula Variable | Mathematical / Clock Reference                                     |\n+------------------+--------------------------------------------------------------------+\n| **$t$**          | Normalized phase time across one LFO cycle ($0.0 \\rightarrow 1.0$).|\n+------------------+--------------------------------------------------------------------+\n| **$x$**          | Input modulation signal or secondary modulator value.              |\n+------------------+--------------------------------------------------------------------+\n| **$rand()$**     | True white-noise pseudo-random float generator ($0.0 - 1.0$).      |\n+------------------+--------------------------------------------------------------------+\n| **$tempo$**      | Current DAW project BPM tempo.                                     |\n+------------------+--------------------------------------------------------------------+</pre>"},{"type":"prose","html":"<strong>Sources:</strong>"},{"type":"list","items":["<em>Surge XT User Manual</em>, Section 5.6 (Formula Engine Reference)"],"ordered":false}]}],"minutes":8},{"id":"sounddesign-l-b-2","title":"B1.2 — Essential Mathematical Modulator Scripts","blocks":[{"type":"step","title":"B1.2 — Essential Mathematical Modulator Scripts","blocks":[{"type":"prose","html":"<pre style=\"white-space:pre-wrap;font-family:ui-monospace,monospace\">1. PARABOLIC EXPONENTIAL DROP:\n   y = 1.0 - (t * t)\n   (Generates a steep quadratic decay curve ideal for punchy percussive filter drops)\n\n2. RECTIFIED FULL-WAVE SINE:\n   y = abs(sin(2 * pi * t * 2))\n   (Doubles the modulation frequency and produces bouncing rubber-ball sweeps)\n\n3. STEPPED RANDOM WALK (CHAOS GENERATOR):\n   y = clamp(y + (rand() - 0.5) * 0.1, -1.0, 1.0)\n   (Generates continuous organic Brownian motion drift for vintage analog pitch instability)</pre>"},{"type":"prose","html":"<strong>Sources:</strong>"},{"type":"list","items":["<em>Surge XT User Manual</em>, Section 5.6"],"ordered":false}]}],"minutes":8}],"exercises":[]},{"id":"sounddesign-m-2-2","code":"2","title":"Bonus Section B2 — Max for Live Sound-Design Devices","blurb":"- Operate Max for Live modulation tools included with your Max for Live add-on: LFO, Shaper, Envelope Follower, and Expression Control. - Cross-modulate third-party VST3 parameters (Vital, Surge XT) directly from Ableton's track control dom","outcomes":[],"sources":[],"practiceFocus":[],"checkpoints":[],"lessons":[{"id":"sounddesign-l-o-64","title":"Section overview","blocks":[{"type":"step","title":"Learning Objectives","blocks":[{"type":"list","items":["Operate Max for Live modulation tools included with your Max for Live add-on: <strong><code>LFO</code></strong>, <strong><code>Shaper</code></strong>, <strong><code>Envelope Follower</code></strong>, and <strong><code>Expression Control</code></strong>.","Cross-modulate third-party VST3 parameters (Vital, Surge XT) directly from Ableton's track control domain.","Build dynamic sound design patches using <strong>Envelope Follower</strong> (sidechaining synth cutoff directly to a dynamic drum transient).","Combine multiple Max for Live modulators into an autonomous generative soundscape."],"ordered":false}]}],"minutes":8},{"id":"sounddesign-l-b-3","title":"B2.1 — The Max for Live Modulation Suite","blocks":[{"type":"step","title":"B2.1 — The Max for Live Modulation Suite","blocks":[{"type":"prose","html":"Max for Live extends Live 12 into a fully modular synthesis environment by allowing dedicated modulation devices to map to <em>any parameter in the entire Live set</em>:"},{"type":"prose","html":"<pre style=\"white-space:pre-wrap;font-family:ui-monospace,monospace\">+---------------------------------------------------------------------------------------------------+\n|                                 MAX FOR LIVE MODULATION SUITE                                     |\n+-------------------+-------------------------------------------------------------------------------+\n| DEVICE            | MODULATION FUNCTION &amp; SOUND DESIGN UTILITY                                    |\n+-------------------+-------------------------------------------------------------------------------+\n| **LFO**           | Multi-waveform, tempo-synced LFO capable of mapping to 8 targets with smooth  |\n|                   | jitter, phase offset, and rate acceleration.                                  |\n+-------------------+-------------------------------------------------------------------------------+\n| **Shaper**        | Multi-node vector MSEG drawing canvas; creates complex custom cyclic curves.  |\n+-------------------+-------------------------------------------------------------------------------+\n| **Envelope Follower**| Analyzes incoming audio amplitude and outputs a dynamic modulation voltage. |\n|                   | (Allows a live vocal or drum track to open a synth's filter cutoff).          |\n+-------------------+-------------------------------------------------------------------------------+\n| **Expression Ctrl**| Remaps Velocity, Mod Wheel, Pitch Bend, and Aftertouch across 8 custom targets.|\n+-------------------+-------------------------------------------------------------------------------+</pre>"},{"type":"prose","html":"<pre style=\"white-space:pre-wrap;font-family:ui-monospace,monospace\">[ MAX FOR LIVE LFO ] ===(Map Button)===&gt; [ VITAL VST3: Filter 1 Cutoff Knob ]\n                                                       |\n                                                       v\n                                      [ Modulates VST3 Parameter Directly from Live! ]</pre>"},{"type":"prose","html":"<strong>Sources:</strong>"},{"type":"list","items":["<em>Ableton Live 12 Reference Manual</em>, Chapter 27 (Max for Live Devices)","<em>Sound-Design-Beginner-Knowledgebase.md</em>, §9"],"ordered":false}]}],"minutes":8},{"id":"sounddesign-l-b-4","title":"B2.2 — Envelope Follower: Dynamic Audio-Rate Modulation","blocks":[{"type":"step","title":"B2.2 — Envelope Follower: Dynamic Audio-Rate Modulation","blocks":[{"type":"prose","html":"<pre style=\"white-space:pre-wrap;font-family:ui-monospace,monospace\">[ LIVE DRUM BUS AUDIO ] ===&gt; [ ENVELOPE FOLLOWER (Rise: 0ms, Fall: 140ms) ]\n                                            |\n                                            v (Outputs Continuous Volume Curve)\n                                  [ MAPPED TO VITAL CUTOFF ]</pre>"},{"type":"list","items":["When the acoustic snare strikes, the Envelope Follower instantly opens Vital's filter cutoff, locking the synth's brightness dynamically to the drummer's physical performance."],"ordered":false},{"type":"prose","html":"<strong>Sources:</strong>"},{"type":"list","items":["<em>Ableton Live 12 Reference Manual</em>, Chapter 27"],"ordered":false}]}],"minutes":8}],"exercises":[]},{"id":"sounddesign-m-3-3","code":"3","title":"Bonus Section B3 — Microtuning and Scale-Aware Sound Design","blurb":"- Operate Ableton Live 12's global Tuning & Scale Awareness Engine. - Load and apply non-Western, historical, and microtonal Scala tuning files (.ascl, .scl).","outcomes":[],"sources":[],"practiceFocus":[],"checkpoints":[],"lessons":[{"id":"sounddesign-l-o-65","title":"Section overview","blocks":[{"type":"step","title":"Learning Objectives","blocks":[{"type":"list","items":["Operate Ableton Live 12's global <strong>Tuning &amp; Scale Awareness Engine</strong>.","Load and apply non-Western, historical, and microtonal Scala tuning files (<code>.ascl</code>, <code>.scl</code>).","Analyze the physical acoustic impact of <strong>Just Intonation</strong> vs. <strong>12-Tone Equal Temperament</strong> on synthesizer overtone beating and FM sidebands.","Configure Surge XT and Vital for global microtuning synchronization."],"ordered":false}]}],"minutes":8},{"id":"sounddesign-l-b-5","title":"B3.1 — Live 12 Global Microtuning Architecture","blocks":[{"type":"step","title":"B3.1 — Live 12 Global Microtuning Architecture","blocks":[{"type":"prose","html":"Ableton Live 12 introduces native <strong>Global Tuning Systems</strong>:"},{"type":"prose","html":"<pre style=\"white-space:pre-wrap;font-family:ui-monospace,monospace\">[ LIVE 12 MASTER TUNING ENGINE ] ===(Broadcasts Tuning File)===&gt; +---&gt; [ DRIFT / OPERATOR ]\n                                                                 +---&gt; [ SURGE XT (VST3)   ]\n                                                                 +---&gt; [ VITAL (VST3)      ]</pre>"},{"type":"list","items":["When a microtonal tuning (e.g., Arabic Maqam Rast, Gamelan Pelog, 19-EDO) is loaded in Live's Control Bar, all native instruments and compatible VST3 plugins automatically remap their oscillator frequencies to the exact microtonal scale."],"ordered":false},{"type":"prose","html":"<strong>Sources:</strong>"},{"type":"list","items":["<em>Ableton Live 12 Reference Manual</em>, Chapter 11 (Tuning Systems)"],"ordered":false}]}],"minutes":8},{"id":"sounddesign-l-b-6","title":"B3.2 — Just Intonation vs. Equal Temperament in FM Synthesis","blocks":[{"type":"step","title":"B3.2 — Just Intonation vs. Equal Temperament in FM Synthesis","blocks":[{"type":"prose","html":"In 12-Tone Equal Temperament (12-TET), musical intervals are compromised slightly so instruments can play in any key (e.g., the Major Third is 14 cents sharp compared to pure physics)."},{"type":"prose","html":"<pre style=\"white-space:pre-wrap;font-family:ui-monospace,monospace\">12-TET Major Third:   f_ratio = 1.25992 (Causes subtle beating when FM modulated)\nJust Intonation Third: f_ratio = 1.25000 (Pure 5:4 integer ratio -&gt; 100% Phase Locked Consonance!)</pre>"},{"type":"prose","html":"When designing FM chords or lush supersaws in <strong>Just Intonation</strong>, all phase beating between harmonics disappears completely, producing crystalline, pure consonant resonance."},{"type":"prose","html":"<strong>Sources:</strong>"},{"type":"list","items":["<em>Ultimate Sound Design: Mastering Sound Design</em>, Section 14.1 (Microtuning Physics)"],"ordered":false}]}],"minutes":8}],"exercises":[]},{"id":"sounddesign-m-4-4","code":"4","title":"Bonus Section B4 — MPE (MIDI Polyphonic Expression) Sound Design","blurb":"- Define the operational architecture of MPE (MIDI Polyphonic Expression) across its three independent physical axes: Pitch Bend (X-Axis), Slide / Y-Axis (CC 74), and Pressure / Z-Axis (Channel Aftertouch). - Configure per-voice polyphonic ","outcomes":[],"sources":[],"practiceFocus":[],"checkpoints":[],"lessons":[{"id":"sounddesign-l-o-66","title":"Section overview","blocks":[{"type":"step","title":"Learning Objectives","blocks":[{"type":"list","items":["Define the operational architecture of <strong>MPE (MIDI Polyphonic Expression)</strong> across its three independent physical axes: <strong>Pitch Bend (X-Axis)</strong>, <strong>Slide / Y-Axis (CC 74)</strong>, and <strong>Pressure / Z-Axis (Channel Aftertouch)</strong>.","Configure per-voice polyphonic expression modulation in <code>Drift</code>, <code>Vital</code>, and <code>Surge XT</code>.","Synthesize an expressive polyphonic acoustic violin/cello patch where each individual finger independently controls pitch vibrato and bow pressure inside a chord."],"ordered":false}]}],"minutes":8},{"id":"sounddesign-l-b-7","title":"B4.1 — The Three Axes of MPE","blocks":[{"type":"step","title":"B4.1 — The Three Axes of MPE","blocks":[{"type":"prose","html":"Traditional MIDI transmits Pitch Bend and Channel Pressure globally across all voices simultaneously. <strong>MPE transmits dedicated MIDI channels per note (1 - 15)</strong>, enabling independent multidimensional control over every single voice in a polyphonic chord:"},{"type":"prose","html":"<pre style=\"white-space:pre-wrap;font-family:ui-monospace,monospace\">+---------------------------------------------------------------------------------------------------+\n|                                        THE THREE MPE DIMENSIONS                                   |\n+-------------------+-----------------------------+-------------------------------------------------+\n| PHYSICAL AXIS     | MIDI PARAMETER STREAM       | ACOUSTIC SOUND DESIGN MAPPING                   |\n+-------------------+-----------------------------+-------------------------------------------------+\n| **X-Axis (Glide)**| Per-Note Pitch Bend ($\\pm 48$ st)| Individual finger vibrato and note slides.     |\n+-------------------+-----------------------------+-------------------------------------------------+\n| **Y-Axis (Slide)**| Per-Note CC 74 (Timbre)     | Vertical finger slide: opens Filter Cutoff/Warp.|\n+-------------------+-----------------------------+-------------------------------------------------+\n| **Z-Axis (Press)**| Per-Note Poly Pressure      | Finger pressure into key: swells Volume/Drive.  |\n+-------------------+-----------------------------+-------------------------------------------------+</pre>"},{"type":"prose","html":"<pre style=\"white-space:pre-wrap;font-family:ui-monospace,monospace\">[ POLYPHONIC CHORD: C3, E3, G3 ]\n  |\n  +---&gt; Finger 1 on C3: Presses harder (Z-Axis) ===&gt; Only C3 swells in volume and drive!\n  +---&gt; Finger 2 on E3: Wiggles left/right (X)  ===&gt; Only E3 undergoes pitch vibrato!\n  +---&gt; Finger 3 on G3: Slides upward (Y-Axis)  ===&gt; Only G3 opens its filter cutoff!</pre>"},{"type":"prose","html":"<strong>Sources:</strong>"},{"type":"list","items":["<em>Ableton Live 12 Reference Manual</em>, Chapter 12 (MPE Editing)","<em>Vital User Manual</em>, Section 5.7 (MPE Support)","<em>Surge XT User Manual</em>, Section 5.7"],"ordered":false}]}],"minutes":8}],"exercises":[]},{"id":"sounddesign-m-5-5","code":"5","title":"Bonus Section B5 — Hardware Control Customization (Launchkey MK4)","blurb":"- Master the integration between Ableton Live 12 and the Novation Launchkey MK4 61. - Configure and switch between Launchkey performance modes: Plugin Mode, Device Mode, and User Custom Modes.","outcomes":[],"sources":[],"practiceFocus":[],"checkpoints":[],"lessons":[{"id":"sounddesign-l-o-67","title":"Section overview","blocks":[{"type":"step","title":"Learning Objectives","blocks":[{"type":"list","items":["Master the integration between Ableton Live 12 and the <strong>Novation Launchkey MK4 61</strong>.","Configure and switch between Launchkey performance modes: <strong>Plugin Mode</strong>, <strong>Device Mode</strong>, and <strong>User Custom Modes</strong>.","Program custom MIDI CC maps via <strong>Novation Components</strong> to bind physical hardware knobs and drum pads to custom Live 12 racks.","Map the 16 velocity-sensitive RGB drum pads for 1-shot percussion triggering and chord map performance."],"ordered":false}]}],"minutes":8},{"id":"sounddesign-l-b-8","title":"B5.1 — Launchkey MK4 Performance Modes","blocks":[{"type":"step","title":"B5.1 — Launchkey MK4 Performance Modes","blocks":[{"type":"prose","html":"<pre style=\"white-space:pre-wrap;font-family:ui-monospace,monospace\">+---------------------------------------------------------------------------------------------------+\n|                                  LAUNCHKEY MK4 PERFORMANCE MODES                                  |\n+-------------------+-------------------------------------------------------------------------------+\n| HARDWARE MODE     | OPERATIONAL CONTROL BEHAVIOR                                                  |\n+-------------------+-------------------------------------------------------------------------------+\n| **Plugin Mode**   | Automatically detects VST3/AU parameters and binds Encoders 1–8 to the first  |\n|                   | 8 macro parameters of the active plugin.                                      |\n+-------------------+-------------------------------------------------------------------------------+\n| **Device Mode**   | Binds Encoders 1–8 directly to the 8 Macro Knobs of an Ableton Instrument Rack.|\n+-------------------+-------------------------------------------------------------------------------+\n| **Custom Mode**   | Unlocks user-defined MIDI CC numbers programmed via Novation Components web app|\n+-------------------+-------------------------------------------------------------------------------+</pre>"},{"type":"prose","html":"<strong>Sources:</strong>"},{"type":"list","items":["<em>Novation Launchkey MK4 User Guide</em>, Section 3 &amp; 4","<em>Ableton-Live-12-VST3-Knowledgebase.md</em>, §4"],"ordered":false}]}],"minutes":8}],"exercises":[]},{"id":"sounddesign-m-6-6","code":"6","title":"Bonus Section B6 — Generative & Algorithmic Sound Design","blurb":"- Design self-evolving, autonomous Generative Soundscapes that play endlessly without human MIDI input. - Deploy Live 12 MIDI Transformation tools: Chance, Velocity Randomization, and Pitch Mapping.","outcomes":[],"sources":[],"practiceFocus":[],"checkpoints":[],"lessons":[{"id":"sounddesign-l-o-68","title":"Section overview","blocks":[{"type":"step","title":"Learning Objectives","blocks":[{"type":"list","items":["Design self-evolving, autonomous <strong>Generative Soundscapes</strong> that play endlessly without human MIDI input.","Deploy Live 12 MIDI Transformation tools: <strong><code>Chance</code></strong>, <strong><code>Velocity Randomization</code></strong>, and <strong><code>Pitch Mapping</code></strong>.","Leverage un-synced poly-rhythmic LFOs across prime number cycle periods (3.0 s, 5.0 s, 7.0 s, 11.0 s) to prevent repetitive looping.","Construct a self-generating generative ambient patch in Surge XT and Vital."],"ordered":false}]}],"minutes":8},{"id":"sounddesign-l-b-9","title":"B6.1 — The Prime Number Modulation Theorem","blocks":[{"type":"step","title":"B6.1 — The Prime Number Modulation Theorem","blocks":[{"type":"prose","html":"To prevent a generative ambient patch from repeating its pattern:"},{"type":"prose","html":"<pre style=\"white-space:pre-wrap;font-family:ui-monospace,monospace\">[ LFO 1: Period = 3.0 Seconds (Prime)  ] ---&gt; Modulates Wavetable Pos\n[ LFO 2: Period = 5.0 Seconds (Prime)  ] ---&gt; Modulates Filter Cutoff\n[ LFO 3: Period = 7.0 Seconds (Prime)  ] ---&gt; Modulates Reverb Decay\n[ LFO 4: Period = 11.0 Seconds (Prime) ] ---&gt; Modulates Stereo Pan</pre>"},{"type":"list","items":["Because all four LFO periods are prime numbers, the mathematical lowest common multiple (3 × 5 × 7 × 11 = 1,155 seconds) ensures the sound design state will <strong>never repeat itself for over 19 minutes of continuous playback</strong>!"],"ordered":false},{"type":"prose","html":"<strong>Sources:</strong>"},{"type":"list","items":["<em>Ultimate Sound Design: Mastering Sound Design</em>, Section 14.2 (Generative Systems)"],"ordered":false}]}],"minutes":8}],"exercises":[]},{"id":"sounddesign-m-7-7","code":"7","title":"Bonus Section B7 — Cinematic & Foley Sound Design","blurb":"- Synthesize cinematic sound design elements for film, trailers, and video games: Cinematic Sub Booms / Braams, Whoosh Transitions, Sci-Fi UI Clicks, and Synthetic Foley Textures. - Operate Collision and Tension to simulate physical acousti","outcomes":[],"sources":[],"practiceFocus":[],"checkpoints":[],"lessons":[{"id":"sounddesign-l-o-69","title":"Section overview","blocks":[{"type":"step","title":"Learning Objectives","blocks":[{"type":"list","items":["Synthesize cinematic sound design elements for film, trailers, and video games: <strong>Cinematic Sub Booms / Braams</strong>, <strong>Whoosh Transitions</strong>, <strong>Sci-Fi UI Clicks</strong>, and <strong>Synthetic Foley Textures</strong>.","Operate <code>Collision</code> and <code>Tension</code> to simulate physical acoustic collisions and metal creaks.","Layer real-world recorded foley audio (rain, paper tear, metal keys) with synthetic oscillators."],"ordered":false}]}],"minutes":8},{"id":"sounddesign-l-b-10","title":"B7.1 — Synthesizing the Cinematic Trailer Braam","blocks":[{"type":"step","title":"B7.1 — Synthesizing the Cinematic Trailer Braam","blocks":[{"type":"prose","html":"The modern cinematic \"Braam\" (Inception-style low-brass impact) is synthesized via a multi-layer Instrument Rack:"},{"type":"prose","html":"<pre style=\"white-space:pre-wrap;font-family:ui-monospace,monospace\">[ TRAILER BRAAM INSTRUMENT RACK ]\n  |\n  +---&gt; Chain 1: [ Operator: 35 Hz Sub Sine with Pitch Drop ]\n  |\n  +---&gt; Chain 2: [ Vital: Saturated Sallen-Key 24 dB Brass Squelch (+12 st Scoop) ]\n  |\n  +---&gt; Chain 3: [ Saturator: Analog Clip (+10 dB) -&gt; Multiband OTT (80%) ]\n  |\n  +---&gt; Chain 4: [ Hybrid Reverb: Large Canyon Convolution Space (Decay: 6.0 s) ]</pre>"},{"type":"prose","html":"<em>Result:</em> An earth-shaking, authoritative trailer blast that cuts through dense orchestral arrangements."},{"type":"prose","html":"<strong>Sources:</strong>"},{"type":"list","items":["<em>Ultimate Sound Design: Mastering Sound Design</em>, Section 14.3 (Cinematic Sound Design)"],"ordered":false}]}],"minutes":8}],"exercises":[]},{"id":"sounddesign-m-8-8","code":"8","title":"Bonus Section B8 — Live Performance Sound-Design Racks","blurb":"- Architect high-reliability, zero-latency Live Performance Sound-Design Racks in Ableton Live 12. - Configure safe CPU limits (<40% buffer safety headroom) and optimize voice allocations.","outcomes":[],"sources":[],"practiceFocus":[],"checkpoints":[],"lessons":[{"id":"sounddesign-l-o-70","title":"Section overview","blocks":[{"type":"step","title":"Learning Objectives","blocks":[{"type":"list","items":["Architect high-reliability, zero-latency <strong>Live Performance Sound-Design Racks</strong> in Ableton Live 12.","Configure safe CPU limits (&lt;40% buffer safety headroom) and optimize voice allocations.","Implement <strong>Global Master Filter Sweep &amp; Beat-Repeat Drop Racks</strong> for live DJ/producer sets.","Build fail-safe preset switching protocols using Chain Selectors."],"ordered":false}]}],"minutes":8},{"id":"sounddesign-l-b-11","title":"B8.1 — Live Performance Safety & CPU Optimization","blocks":[{"type":"step","title":"B8.1 — Live Performance Safety & CPU Optimization","blocks":[{"type":"prose","html":"During live performance on stage, an audio glitch or CPU spike destroys the performance."},{"type":"prose","html":"<pre style=\"white-space:pre-wrap;font-family:ui-monospace,monospace\">+---------------------------------------------------------------------------------------------------+\n|                              LIVE PERFORMANCE STABILITY RULES                                     |\n+------------------------------------+--------------------------------------------------------------+\n| 1. AUDIO BUFFER CALIBRATION        | Set ASIO Buffer to **256 Samples ($5.8\\text{ ms}$)**.         |\n+------------------------------------+--------------------------------------------------------------+\n| 2. POLYPHONY LIMITS                | Cap all synthesizer polyphony at **6 Voices** (Mono on bass).|\n+------------------------------------+--------------------------------------------------------------+\n| 3. NO HIGH-OVERHEAD OVERSAMPLING   | Disable $8\\times$ oversampling inside plugins during live sets.|\n+------------------------------------+--------------------------------------------------------------+\n| 4. HARDWARE FAIL-SAFE RACKS        | Map all 8 Launchkey MK4 encoders to high-impact master macros.|\n+------------------------------------+--------------------------------------------------------------+</pre>"},{"type":"prose","html":"<strong>Sources:</strong>"},{"type":"list","items":["<em>Ableton Live 12 Reference Manual</em>, Chapter 24","<em>Sound-Design-Beginner-Knowledgebase.md</em>, §3"],"ordered":false}]}],"minutes":8}],"exercises":[]},{"id":"sounddesign-m-9-9","code":"9","title":"Bonus Section B9 — Comprehensive Synth Percussion Masterclass","blurb":"- Master the universal acoustic physics of Drum Synthesis: decomposing percussion sounds into Transient Strike (Click), Tonal Resonant Body (Thud), and Noise Dispersion (Sizzle/Wires). - Synthesize all core electronic drum types completely ","outcomes":[],"sources":[],"practiceFocus":[],"checkpoints":[],"lessons":[{"id":"sounddesign-l-o-71","title":"Section overview","blocks":[{"type":"step","title":"Learning Objectives","blocks":[{"type":"list","items":["Master the universal acoustic physics of <strong>Drum Synthesis</strong>: decomposing percussion sounds into <strong>Transient Strike (Click)</strong>, <strong>Tonal Resonant Body (Thud)</strong>, and <strong>Noise Dispersion (Sizzle/Wires)</strong>.","Synthesize all core electronic drum types completely from scratch across multiple synthesis paradigms (Subtractive, FM, Additive, Physical Modeling):","<strong>Electronic Kick Drums</strong> (808, 909, Hardstyle, Punchy House)","<strong>Electronic Snare Drums</strong> (Acoustic snare emulation, 909 tonal snap, 808 noise burst)","<strong>Hand Claps</strong> (Multi-burst micro-flam transients + stereo noise decay)","<strong>Closed &amp; Open Hi-Hats</strong> (Inharmonic FM metallic grids + 6-oscillator arrays)","<strong>Acoustic &amp; Synthetic Toms</strong> (Pitch-dropped membrane resonances)","<strong>Crash Cymbals &amp; Metallic Rides</strong> (Dense inharmonic sidebands + high-pass diffusion)","<strong>Auxiliary Percussion</strong> (Cowbells, Rimshots, Woodblocks, Shakers)","Assemble individual synthesized drum patches into a fully responsive, playable <strong>Ableton Drum Rack</strong> with dedicated macro parameter controls."],"ordered":false}]}],"minutes":8},{"id":"sounddesign-l-b-12","title":"B9.1 — The Universal Physics of Drum Synthesis","blocks":[{"type":"step","title":"B9.1 — The Universal Physics of Drum Synthesis","blocks":[{"type":"prose","html":"Every percussive sound in acoustic and electronic music is structured into three discrete physical time stages:"},{"type":"prose","html":"<pre style=\"white-space:pre-wrap;font-family:ui-monospace,monospace\">Amplitude (dBFS)\n  0 dB | |\\  &lt;--- 1. THE TRANSIENT (0 to 15 ms): Hard physical beater/stick strike\n       | | \\\n-12 dB | |  \\======== 2. THE TONAL BODY (15 to 200 ms): Pitch-dropping resonant membrane\n       | |           \\\n-36 dB | |            \\-------- 3. THE NOISE / DECAY TAIL (200 to 800 ms): Snare wires / room space\n-inf dB+-+------------+--------+----------------------------------------------------&gt; Time (ms)</pre>"},{"type":"prose","html":"<pre style=\"white-space:pre-wrap;font-family:ui-monospace,monospace\">+---------------------------------------------------------------------------------------------------+\n|                                  THE 3-STAGE PERCUSSION MATRIX                                    |\n+-------------------+-----------------------------+-----------------------+-------------------------+\n| PERCUSSION STAGE  | TIME DURATION               | ACOUSTIC MECHANISM    | SYNTHESIS METHOD        |\n+-------------------+-----------------------------+-----------------------+-------------------------+\n| **1. Transient**  | $0\\text{ ms} - 15\\text{ ms}$| Impact click / stick  | Fixed FM, Noise burst,  |\n|                   |                             | hardness on membrane. | Ultra-fast pitch drop.  |\n+-------------------+-----------------------------+-----------------------+-------------------------+\n| **2. Tonal Body** | $15\\text{ ms} - 250\\text{ ms}$| Fundamental membrane  | Sine / Triangle wave    |\n|                   |                             | air vibration in drum.| with pitch envelope.    |\n+-------------------+-----------------------------+-----------------------+-------------------------+\n| **3. Noise Tail** | $50\\text{ ms} - 800\\text{ ms}$| Snare wire friction,  | White / Pink noise,     |\n|                   |                             | cymbal metal shimmer. | Inharmonic FM metal.    |\n+-------------------+-----------------------------+-----------------------+-------------------------+</pre>"},{"type":"prose","html":"<strong>Sources:</strong>"},{"type":"list","items":["<em>Sound-Design-Beginner-Knowledgebase.md</em>, §15 (Percussion Synthesis)","<em>Ultimate Sound Design: Mastering Sound Design</em>, Section 15.1"],"ordered":false}]}],"minutes":8},{"id":"sounddesign-l-b-13","title":"B9.2 — Synthesizing Electronic Kick Drums","blocks":[{"type":"step","title":"B9.2 — Synthesizing Electronic Kick Drums","blocks":[{"type":"prose","html":"A kick drum is synthesized using a pure sine wave whose pitch drops rapidly from high frequencies down to a deep sub-bass fundamental:"},{"type":"prose","html":"<pre style=\"white-space:pre-wrap;font-family:ui-monospace,monospace\">[ PITCH ENVELOPE (+36 st to 0 st in 25 ms) ] ===&gt; [ OSCILLATOR: Pure Sine Wave ] ===&gt; [ AMP ENVELOPE ]\n                                                               |\n                                            Pitch starts at 400 Hz -&gt; Drops to 50 Hz</pre>"},{"type":"prose","html":"<pre style=\"white-space:pre-wrap;font-family:ui-monospace,monospace\">+-------------------------------------------------------------------------------+\n| PATCH SPECIFICATION: PUNCHY ELECTRONIC KICK                                   |\n+-------------------------------------------------------------------------------+\n| **SYNTH ENGINE**     | **Ableton Operator** (or Drift / Surge XT)             |\n| **ALGORITHM**        | **Algorithm 4** (Dual 2-Op)                            |\n| **OSC A (Sub Body)** | Mode: **Ratio**, Wave: **Sine**, Coarse: **0.5** (48 Hz)|\n|                      | Level: **0.0 dB**, AEG Decay: **380 ms**, Sustain: **0.0**|\n| **OSC B (Click)**    | Mode: **Fixed (1.5 kHz)**, Level: **-12 dB**, Decay: **12 ms**|\n| **PITCH ENVELOPE**   | Amount: **+24 semitones**, Decay: **25 ms**            |\n| **DOWNSTREAM FX**    | `Saturator` (Soft Sine: +2 dB) -&gt; `Utility` (Mono)     |\n+-------------------------------------------------------------------------------+</pre>"},{"type":"list","items":["<strong>Hardstyle Kick Variant:</strong> Route the kick through <code>Overdrive</code> (Drive +15 dB) and a 24 dB Band-Pass filter sweeping from 1 kHz to 200 Hz.","<strong>808 Kick Variant:</strong> Extend AEG Decay to 1.8 seconds and reduce pitch envelope amount to +18 st."],"ordered":false},{"type":"prose","html":"<strong>Sources:</strong>"},{"type":"list","items":["<em>Sound-Design-Beginner-Knowledgebase.md</em>, §15","<em>Ableton Live 12 Reference Manual</em>, Chapter 23"],"ordered":false}]}],"minutes":8},{"id":"sounddesign-l-b-14","title":"B9.3 — Synthesizing Electronic Snare Drums","blocks":[{"type":"step","title":"B9.3 — Synthesizing Electronic Snare Drums","blocks":[{"type":"prose","html":"An acoustic snare consists of a wooden shell (180-220 Hz) and metal coiled snare wires vibrating against the bottom drumhead:"},{"type":"prose","html":"<pre style=\"white-space:pre-wrap;font-family:ui-monospace,monospace\">[ LAYER 1: TONAL BODY ] ---&gt; Sine wave @ 200 Hz with pitch drop (40 ms) ---+\n                                                                           |===&gt; [ COMBINED SNARE ]\n[ LAYER 2: NOISE WIRES] ---&gt; High-passed White Noise (Decay 220 ms) -------+</pre>"},{"type":"prose","html":"<pre style=\"white-space:pre-wrap;font-family:ui-monospace,monospace\">+-------------------------------------------------------------------------------+\n| PATCH SPECIFICATION: SYNTHETIC DUAL-LAYER SNARE                               |\n+-------------------------------------------------------------------------------+\n| **SYNTH ENGINE**     | **Ableton Operator** (Algorithm 4)                     |\n| **OSC A (Tonal)**    | Wave: **Sine**, Coarse: **1** (200 Hz), Level: **0 dB**|\n|                      | Pitch Env: **+14 st**, Pitch Decay: **35 ms**          |\n|                      | AEG Decay: **160 ms**, Sustain: **0.0**                |\n| **OSC C (Wires)**    | Mode: **Fixed (8.5 kHz)**, Wave: **Noise White**       |\n|                      | Level: **-4.0 dB**, AEG Decay: **240 ms**, Sust: **0.0**|\n| **FILTER**           | Mode: **High-Pass HP12**, Cutoff: **180 Hz**          |\n| **DOWNSTREAM FX**    | `Dynamic Tube` (Drive +4 dB) -&gt; `Glue Compressor`      |\n+-------------------------------------------------------------------------------+</pre>"},{"type":"prose","html":"<strong>Sources:</strong>"},{"type":"list","items":["<em>Ultimate Sound Design: Mastering Sound Design</em>, Section 15.2 (Snare Physics)"],"ordered":false}]}],"minutes":8},{"id":"sounddesign-l-b-15","title":"B9.4 — Synthesizing Hand Claps","blocks":[{"type":"step","title":"B9.4 — Synthesizing Hand Claps","blocks":[{"type":"prose","html":"A real human hand clap is not a single impact; it is multiple hands striking slightly out of sync (micro-flams) followed by a reverberant room tail:"},{"type":"prose","html":"<pre style=\"white-space:pre-wrap;font-family:ui-monospace,monospace\">Micro-Flam Transient Burst:\nStrike 1 (0ms) -&gt; Strike 2 (12ms) -&gt; Strike 3 (24ms) ===&gt; Main Tail Decay (180ms)\n   |                 |                 |                     |\n [|||]             [|||]             [|||]             [||||||||||||||||]</pre>"},{"type":"prose","html":"<pre style=\"white-space:pre-wrap;font-family:ui-monospace,monospace\">+-------------------------------------------------------------------------------+\n| PATCH SPECIFICATION: SYNTHETIC HAND CLAP                                      |\n+-------------------------------------------------------------------------------+\n| **SYNTH ENGINE**     | **Surge XT** (or Vital MSEG)                           |\n| **OSCILLATOR 1**     | Algorithm: **S&amp;H Noise**, Color: **Pink / White**      |\n| **ENVELOPE 1 (AEG)** | **Multi-Trigger MSEG Mode:**                           |\n|                      | - 3 rapid 6ms volume pulses spaced 12ms apart          |\n|                      | - 4th pulse sustains into a 220ms exponential tail     |\n| **FILTER 1**         | Model: **Band-Pass BP24**, Cutoff: **1.4 kHz**, Res: **0.30**|\n| **DOWNSTREAM FX**    | `Reverb` (Decay: 1.2 s, Size: 40%, Mix: 25%)           |\n+-------------------------------------------------------------------------------+</pre>"},{"type":"prose","html":"<strong>Sources:</strong>"},{"type":"list","items":["<em>Sound-Design-Beginner-Knowledgebase.md</em>, §15"],"ordered":false}]}],"minutes":8},{"id":"sounddesign-l-b-16","title":"B9.5 — Synthesizing Closed & Open Hi-Hats","blocks":[{"type":"step","title":"B9.5 — Synthesizing Closed & Open Hi-Hats","blocks":[{"type":"prose","html":"Cymbals and hi-hats do not use harmonic series. They are made of hammered bronze that vibrates with thousands of chaotic, inharmonic metallic modes:"},{"type":"prose","html":"<pre style=\"white-space:pre-wrap;font-family:ui-monospace,monospace\">TR-808 HI-HAT SYNTHESIS MODEL:\n6 Square Wave Oscillators (Inharmonic Freqs: 245Hz, 306Hz, 384Hz, 422Hz, 545Hz, 617Hz)\n                               |\n                               v (Summed together into a chaotic metallic cluster)\n                     [ BAND-PASS FILTER @ 10 kHz ]\n                               |\n                               v\n                     [ HIGH-PASS FILTER @ 8 kHz ]</pre>"},{"type":"prose","html":"<pre style=\"white-space:pre-wrap;font-family:ui-monospace,monospace\">+-------------------------------------------------------------------------------+\n| PATCH SPECIFICATION: INHARMONIC FM CLOSED &amp; OPEN HI-HAT                       |\n+-------------------------------------------------------------------------------+\n| **SYNTH ENGINE**     | **Ableton Operator** (Algorithm 1)                     |\n| **OPERATOR A (Car)** | Mode: **Fixed (6.2 kHz)**, Wave: **Square D**, Level: **0 dB**|\n|                      | **Closed Hat AEG:** Decay **45 ms**, Sustain **0.0**   |\n|                      | **Open Hat AEG:**   Decay **320 ms**, Sustain **0.0**  |\n| **OPERATOR B (Mod)** | Mode: **Fixed (8.73 kHz)**, Level: **-6.0 dB**         |\n| **OPERATOR C (Mod)** | Mode: **Fixed (3.41 kHz)**, Level: **-10.0 dB**        |\n| **FILTER**           | Mode: **High-Pass HP24**, Cutoff: **8.5 kHz**          |\n+-------------------------------------------------------------------------------+</pre>"},{"type":"prose","html":"<strong>Sources:</strong>"},{"type":"list","items":["<em>Ultimate Sound Design: Mastering Sound Design</em>, Section 15.3 (Cymbal Math)"],"ordered":false}]}],"minutes":8},{"id":"sounddesign-l-b-17","title":"B9.6 — Synthesizing Acoustic & Synthetic Toms","blocks":[{"type":"step","title":"B9.6 — Synthesizing Acoustic & Synthetic Toms","blocks":[{"type":"prose","html":"<pre style=\"white-space:pre-wrap;font-family:ui-monospace,monospace\">+-------------------------------------------------------------------------------+\n| PATCH SPECIFICATION: RESONANT ACOUSTIC TOM                                    |\n+-------------------------------------------------------------------------------+\n| **SYNTH ENGINE**     | **Ableton Collision** (or Operator)                   |\n| **MALLET**           | Stiffness: **65%**, Noise: **25%**                     |\n| **RESONATOR 1**      | Model: **Membrane**, Pitch: **110 Hz (A1)**, Decay: **850 ms**|\n|                      | Inharmonics: **High**, Damping: **35%**                |\n| **RESONATOR 2**      | Model: **Pipe** (Simulates hollow drum shell air)      |\n+-------------------------------------------------------------------------------+</pre>"},{"type":"prose","html":"<em>Result:</em> A rich, woody, acoustic tom with authentic drumhead bounce and shell resonance."},{"type":"prose","html":"<strong>Sources:</strong>"},{"type":"list","items":["<em>Ableton Live 12 Reference Manual</em>, Chapter 23 (Collision)"],"ordered":false}]}],"minutes":8},{"id":"sounddesign-l-b-18","title":"B9.7 — Synthesizing Crash Cymbals & Rides","blocks":[{"type":"step","title":"B9.7 — Synthesizing Crash Cymbals & Rides","blocks":[{"type":"prose","html":"<pre style=\"white-space:pre-wrap;font-family:ui-monospace,monospace\">+-------------------------------------------------------------------------------+\n| PATCH SPECIFICATION: SYNTHETIC CRASH CYMBAL                                   |\n+-------------------------------------------------------------------------------+\n| **SYNTH ENGINE**     | **Vital**                                              |\n| **OSCILLATOR 1**     | Table: **Harmonic Series**, Warp: **Inharmonic Smear (85%)**|\n| **OSCILLATOR 2**     | Sample Noise: **White Noise**, Level: **-3 dB**        |\n| **FILTER 1**         | Mode: **Comb+**, Cutoff: **7.5 kHz**, Feedback: **80%**|\n| **ENVELOPE 1 (AEG)** | Attack: **0 ms**, Decay: **3.5 s**, Sustain: **0.0**   |\n| **EFFECTS RACK**     | **Reverb:** Size **85%**, Decay **4.0 s**, Low Cut **400 Hz**|\n+-------------------------------------------------------------------------------+</pre>"},{"type":"prose","html":"<strong>Sources:</strong>"},{"type":"list","items":["<em>Vital User Manual</em>, Section 2 &amp; 7"],"ordered":false}]}],"minutes":8},{"id":"sounddesign-l-b-19","title":"B9.8 — Synthesizing Auxiliary Percussion (Cowbell, Rimshot, Shaker)","blocks":[{"type":"step","title":"B9.8 — Synthesizing Auxiliary Percussion (Cowbell, Rimshot, Shaker)","blocks":[{"type":"prose","html":"<pre style=\"white-space:pre-wrap;font-family:ui-monospace,monospace\">+------------------+-----------------------+----------------------------------------------------+\n| Percussion Sound | Synthesis Engine      | Acoustic Synthesis Recipe                          |\n+------------------+-----------------------+----------------------------------------------------+\n| **808 Cowbell**  | `Operator` (Alg 11)   | Dual Fixed Square Waves ($540\\text{ Hz} + 800\\text{ Hz}$)|\n|                  |                       | through Bandpass filter ($1.2\\text{ kHz}$).        |\n+------------------+-----------------------+----------------------------------------------------+\n| **Woodblock**    | `Collision` (Beam)    | Hard Mallet on small dense wooden Beam ($1.8\\text{ kHz}$).|\n+------------------+-----------------------+----------------------------------------------------+\n| **Rimshot**      | `Drift` / `Operator`  | $400\\text{ Hz}$ sine click + 10ms white noise snap.|\n+------------------+-----------------------+----------------------------------------------------+\n| **Shaker**       | `Operator` Noise      | Band-Pass Pink Noise with $1/16\\text{th}$ volume LFO.|\n+------------------+-----------------------+----------------------------------------------------+</pre>"},{"type":"prose","html":"<strong>Sources:</strong>"},{"type":"list","items":["<em>Sound-Design-Beginner-Knowledgebase.md</em>, §15"],"ordered":false}]}],"minutes":8},{"id":"sounddesign-l-b-20","title":"B9.9 — Assembling the Custom Synth Drum Kit in Drum Rack","blocks":[{"type":"step","title":"B9.9 — Assembling the Custom Synth Drum Kit in Drum Rack","blocks":[{"type":"prose","html":"<pre style=\"white-space:pre-wrap;font-family:ui-monospace,monospace\">[ ABLETON DRUM RACK: \"SD_Custom_SynthKit_Master\" ]\n  |\n  +---&gt; Pad C1:  [ Operator: SD_Kick_Punchy      ] ---&gt; Macro: Kick Pitch &amp; Decay\n  +---&gt; Pad C#1: [ Collision: SD_Rimshot_Wood   ] ---&gt; Macro: Rim Hardness\n  +---&gt; Pad D1:  [ Operator: SD_Snare_DualLayer  ] ---&gt; Macro: Snare Wire Snappiness\n  +---&gt; Pad D#1: [ Surge XT: SD_Clap_MultiFlam  ] ---&gt; Macro: Clap Room Decay\n  +---&gt; Pad F#1: [ Operator: SD_Hat_ClosedFM    ] ---&gt; Macro: Closed Hat Tightness\n  +---&gt; Pad G#1: [ Operator: SD_Hat_OpenFM      ] ---&gt; Macro: Open Hat Sizzle\n  +---&gt; Pad A1:  [ Collision: SD_Tom_LowRes     ] ---&gt; Macro: Tom Shell Resonance\n  +---&gt; Pad A#1: [ Vital: SD_Crash_Inharmonic   ] ---&gt; Macro: Crash Wash Space</pre>"},{"type":"prose","html":"Group all 8 drum generators into a single Drum Rack and map the 8 Launchkey encoders to shape the decay, pitch, and snap of every individual drum voice in real time."},{"type":"prose","html":"<strong>Sources:</strong>"},{"type":"list","items":["<em>Sound-Design-Beginner-Knowledgebase.md</em>, §15 &amp; §16"],"ordered":false}]}],"minutes":8}],"exercises":[]},{"id":"sounddesign-m-10-10","code":"10","title":"Bonus Section B10 — Optional Installed Plugins (Helm, Audible Planets, OB-EZ)","blurb":"- Operate secondary third-party VST3 instruments available in the user environment: Matt Tytel's Helm, Audible Planets, and D16 / DiscoDSP OB-EZ. - Map the universal subtractive and modulation architecture learned in Modules 1–7 onto these ","outcomes":[],"sources":[],"practiceFocus":[],"checkpoints":[],"lessons":[{"id":"sounddesign-l-o-72","title":"Section overview","blocks":[{"type":"step","title":"Learning Objectives","blocks":[{"type":"list","items":["Operate secondary third-party VST3 instruments available in the user environment: <strong>Matt Tytel's Helm</strong>, <strong>Audible Planets</strong>, and <strong>D16 / DiscoDSP OB-EZ</strong>.","Map the universal subtractive and modulation architecture learned in Modules 1–7 onto these specialized plugins.","Synthesize vintage Oberheim SEM brass on <strong>OB-EZ</strong>, cross-modulation patches on <strong>Helm</strong>, and planetary orbital modulations on <strong>Audible Planets</strong>."],"ordered":false}]}],"minutes":8},{"id":"sounddesign-l-b-21","title":"B10.1 — Matt Tytel's Helm: Predecessor to Vital","blocks":[{"type":"step","title":"B10.1 — Matt Tytel's Helm: Predecessor to Vital","blocks":[{"type":"prose","html":"<strong>Helm</strong> is an open-source visual subtractive synthesizer developed by Matt Tytel (the creator of Vital):"},{"type":"prose","html":"<pre style=\"white-space:pre-wrap;font-family:ui-monospace,monospace\">+-------------------------------------------------------------------------------+\n|                            HELM SYNTHESIS FEATURES                            |\n+----------------------+--------------------------------------------------------+\n| **Dual Oscillators** | 2 Virtual Analog Oscillators with Cross-Modulation     |\n|                      | (Hard Sync, Frequency Modulation, and Ring Mod).       |\n+----------------------+--------------------------------------------------------+\n| **Stutter / Arp**    | Built-in rhythmic stutter gate and arpeggiator engine. |\n+----------------------+--------------------------------------------------------+\n| **Visual Mod Grid**  | Early prototype of Vital's drag-and-drop modulation UI.|\n+----------------------+--------------------------------------------------------+</pre>"},{"type":"list","items":["<strong>Application:</strong> Lightweight CPU analog leads, rhythmic stutter gates, and fast FM cross-mod brass."],"ordered":false},{"type":"prose","html":"<strong>Sources:</strong>"},{"type":"list","items":["<em>Helm Synthesizer Official User Guide</em>, Section 1–3"],"ordered":false}]}],"minutes":8},{"id":"sounddesign-l-b-22","title":"B10.2 — OB-EZ: Vintage Oberheim SEM Emulation","blocks":[{"type":"step","title":"B10.2 — OB-EZ: Vintage Oberheim SEM Emulation","blocks":[{"type":"prose","html":"<strong>OB-EZ</strong> provides an accessible emulation of the iconic 1970s <strong>Oberheim 8-Voice / SEM (Synthesizer Expander Module)</strong> analog sound:"},{"type":"list","items":["<strong>Continuous SVF Filter:</strong> Seamlessly sweeps from 12 dB Low-Pass through Notch into High-Pass.","<strong>Iconic 80s Analog Brass:</strong> Two detuned sawtooth waves with gentle filter envelope decay, full filter resonance, and stereo voice spread instantly delivers the signature Van Halen <em>\"Jump\"</em> / Prince vintage polysynth brass."],"ordered":false},{"type":"prose","html":"<strong>Sources:</strong>"},{"type":"list","items":["<em>OB-EZ Instrument Manual</em>, Section 1"],"ordered":false}]}],"minutes":8},{"id":"sounddesign-l-b-23","title":"B10.3 — Audible Planets: Orbital Modulation Synthesis","blocks":[{"type":"step","title":"B10.3 — Audible Planets: Orbital Modulation Synthesis","blocks":[{"type":"prose","html":"<strong>Audible Planets</strong> models celestial orbital physics as modulation sources:"},{"type":"list","items":["<strong>Gravitational Trajectories:</strong> Modulators travel along gravitational orbital paths around virtual planetary bodies, generating unique non-repeating, semi-periodic modulation vectors for evolving space ambient soundscapes."],"ordered":false},{"type":"prose","html":"<strong>Sources:</strong>"},{"type":"list","items":["<em>Audible Planets User Documentation</em>, Section 1"],"ordered":false}]}],"minutes":8}],"exercises":[]}]};
